"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["45350"],{45261(e){e.exports=JSON.parse('{"id":"V4-197","slug":"event-driven-strategy","term":"Event-Driven Strategy","also_known_as":[],"difficulty":"Advanced","definition":"An event-driven strategy is an investment approach that aims to profit from price movements caused by specific corporate events, such as mergers, acquisitions, bankruptcies, restructurings, spin-offs or shareholder activism.","explanation":["Event-driven investors analyse how particular events are likely to affect the prices of a company\u2019s shares or bonds, and take positions to profit from those changes.","Common event-driven strategies include merger arbitrage, which involves buying shares of a company being acquired and sometimes shorting the acquirer\u2019s shares, aiming to profit from the gap between the current price and the offer price; distressed investing, buying the debt or shares of companies in financial difficulty or bankruptcy, betting on a recovery; special situations, such as spin-offs, share buybacks and restructurings; and activist investing, buying stakes to push for changes.","For example, if a company agrees to be acquired for 50 per share and its shares trade at 48, a merger arbitrage investor might buy them, expecting to earn 2 per share when the deal closes.","Event-driven returns depend more on whether specific events happen as expected than on the overall direction of markets. The main risk is that deals fail or events turn out differently, which can cause large losses. Event-driven strategies are often affected by economic conditions, regulation and deal activity."],"note":"","total":1725,"prev":{"slug":"ev-revenue","term":"EV/Revenue"},"next":{"slug":"evergreen-fund","term":"Evergreen Fund"}}')}}]);